// ==UserScript==
// @name         Veyra Theme Studio
// @namespace    uanm.veyra
// @version      0.9.7
// @description  Theme Studio for every Veyra page: themes with animated effects and painted art, your own background with auto palette, fonts, Live mode (boss alerts, stamina mood, day/night, parallax, particle words), redesigned Inventory / Pets / Power Crystals / Black Merchant / Guild pages (each can be switched back to the original), Discord #game-talk button and mini games.
// @author       UANM
// @copyright    2026 UANM. All rights reserved. Redistribution or modification without permission is not allowed.
// @match        https://demonicscans.org/*
// @updateURL    https://raw.githubusercontent.com/stizzen-create/veyra-theme-studio/main/veyra_theme_studio.user.js
// @downloadURL  https://raw.githubusercontent.com/stizzen-create/veyra-theme-studio/main/veyra_theme_studio.user.js
// @grant        none
// @run-at       document-start
// ==/UserScript==

(function () {
  'use strict';
  var SIG = "Veyra scripts by UANM";
  var meta = (typeof GM_info !== 'undefined' && (GM_info.scriptMetaStr || '')) || '';
  var au = (meta.match(/@author\s+(.+)/) || [])[1] || (typeof GM_info !== 'undefined' && GM_info.script && GM_info.script.author) || '';
  var key = SIG + '|' + String(au).trim();
  var x = 0x811c9dc5, i;
  for (i = 0; i < key.length; i++) { x ^= key.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; }
  x = x || 1;
  var bin = atob(""), bytes = new Uint8Array(bin.length);
  for (i = 0; i < bin.length; i++) {
    x ^= x << 13; x >>>= 0; x ^= x >>> 17; x ^= x << 5; x >>>= 0;
    bytes[i] = bin.charCodeAt(i) ^ (x & 255);
  }
  var code;
  try { code = new TextDecoder('utf-8', { fatal: true }).decode(bytes); } catch (e) { return; }
  if (code.indexOf("/*UANM-OK*/") !== 0) return;
  (0, eval)(code + '\n//# sourceURL=' + "veyra_theme_studio.user.js");
})();
